//! Script modules: any executable in `<config dir>/modules/` is a card. It prints a few plain lines
//! (see AGENTS.md); halftone runs it on its own interval in a thread and draws the last good output.

use super::config;
use std::collections::HashMap;
use std::io::Read;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::mpsc::{self, Receiver, Sender};
use std::time::{Duration, Instant};

// Shipped modules, written into the modules dir when missing and never overwritten after.
// Generated by build.rs from every file in modules/.
include!(concat!(env!("OUT_DIR"), "/builtin.rs"));

pub const AGENTS: &str = include_str!("../../AGENTS.md");

pub const SCAFFOLD: &str = "#!/bin/sh
# A halftone module: print lines, halftone draws them. Test with:  halftone module run NAME
# Each line is `kind: value`; unprefixed lines are muted text. Kinds:
#   title: Card title            every: 60 (seconds between runs)
#   open: https://... or a shell command (Enter / click on the card)
#   big: bold headline           text: quiet line           error: red line
#   row: label | value | tone     tone is good bad warn muted accent (optional)
#   bar: label | 0.0-1.0 | tone  spark: 1 3 2 5 8 (one-line sparkline)
#   link: label | url            clickable row
#   connect: name | url | what to paste   ask for a token; read it back: halftone secret get name
echo \"title: NAME\"
echo \"every: 60\"
echo \"big: hello\"
echo \"row: time | $(date +%H:%M) | accent\"
echo \"bar: minute | $(awk -v m=$(date +%M) 'BEGIN{print m/60}') | good\"
";

#[derive(Clone, Debug, PartialEq)]
pub enum Line {
    Big(String),
    Row(String, String, Option<String>),
    Bar(String, f32, Option<String>),
    Spark(Vec<f32>),
    /// label, url, and a dim note on the right (points, a time)
    Link(String, String, String),
    /// a small heading that starts a group
    Head(String),
    Text(String),
    Error(String),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Out {
    pub title: Option<String>,
    pub every: u64,
    pub open: Option<String>,
    /// `connect: name | url | what to paste`: the card asks for a secret before it has data.
    pub connect: Option<(String, String, String)>,
    pub lines: Vec<Line>,
}

pub fn parse(text: &str) -> Out {
    let mut o = Out { title: None, every: 60, open: None, connect: None, lines: vec![] };
    for raw in text.lines() {
        let line = raw.trim_end();
        if line.trim().is_empty() {
            continue;
        }
        let (key, rest) = line.split_once(':').map_or(("", line), |(k, r)| (k.trim(), r.trim()));
        let p: Vec<&str> = rest.split('|').map(str::trim).collect();
        let tone = |i: usize| p.get(i).filter(|t| !t.is_empty()).map(|t| t.to_string());
        match key {
            "title" => o.title = Some(rest.into()),
            "every" => o.every = rest.parse::<u64>().unwrap_or(60).max(2),
            "open" => o.open = Some(rest.into()),
            "connect" => match p.as_slice() {
                [name, url, ..] if !name.is_empty() && !url.is_empty() => o.connect = Some((name.to_string(), url.to_string(), p.get(2).filter(|s| !s.is_empty()).unwrap_or(&"your key").to_string())),
                _ => o.lines.push(Line::Text(line.trim().into())),
            },
            "big" => o.lines.push(Line::Big(rest.into())),
            "row" => o.lines.push(Line::Row(p[0].into(), p.get(1).unwrap_or(&"").to_string(), tone(2))),
            "bar" => o.lines.push(Line::Bar(p[0].into(), p.get(1).and_then(|v| v.parse().ok()).unwrap_or(0.0f32).clamp(0.0, 1.0), tone(2))),
            "spark" => o.lines.push(Line::Spark(rest.split(|c: char| c.is_whitespace() || c == ',').filter_map(|n| n.parse().ok()).collect())),
            "link" => match p.as_slice() {
                [label, url, rest @ ..] => o.lines.push(Line::Link(label.to_string(), url.to_string(), rest.first().unwrap_or(&"").to_string())),
                _ => o.lines.push(Line::Text(rest.into())),
            },
            "head" => o.lines.push(Line::Head(rest.into())),
            "text" => o.lines.push(Line::Text(rest.into())),
            "error" => o.lines.push(Line::Error(rest.into())),
            _ => o.lines.push(Line::Text(line.trim().into())),
        }
    }
    o
}

pub fn dir() -> PathBuf {
    config::path().parent().map_or_else(|| PathBuf::from("modules"), |d| d.join("modules"))
}

/// "todoist" -> "Todoist"
pub fn cap(s: &str) -> String {
    let mut c = s.chars();
    c.next().map_or(String::new(), |f| f.to_uppercase().chain(c).collect())
}

fn valid(name: &str) -> bool {
    !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

pub fn path(name: &str) -> PathBuf {
    dir().join(name)
}

pub fn exists(name: &str) -> bool {
    valid(name) && std::fs::metadata(path(name)).is_ok_and(|m| m.is_file())
}

/// The names of every module in the modules dir, sorted.
pub fn list() -> Vec<String> {
    let mut v: Vec<String> = std::fs::read_dir(dir()).into_iter().flatten().flatten().map(|e| e.file_name().to_string_lossy().into_owned()).filter(|n| exists(n)).collect();
    v.sort();
    v
}

/// (`# about:` line, `# group:` line) from a script's first 5 lines.
pub fn meta(body: &str) -> (String, String) {
    let (mut about, mut group) = (String::new(), String::new());
    for l in body.lines().take(5) {
        let l = l.trim_start_matches('#').trim();
        if let Some(a) = l.strip_prefix("about:") {
            about = a.trim().into();
        } else if let Some(g) = l.strip_prefix("group:") {
            group = g.trim().into();
        }
    }
    (about, group)
}

#[cfg(unix)]
pub fn make_exec(p: &std::path::Path) {
    use std::os::unix::fs::PermissionsExt;
    let _ = std::fs::set_permissions(p, std::fs::Permissions::from_mode(0o755));
}
#[cfg(not(unix))]
pub fn make_exec(_: &std::path::Path) {}

/// Writes the shipped modules and AGENTS.md. A copy of what was shipped sits in `.shipped/`, so an
/// update replaces a file you never edited and leaves the ones you changed alone.
pub fn install() {
    let d = dir();
    let kept = d.join(".shipped");
    let _ = std::fs::create_dir_all(&kept);
    let files = BUILTIN.iter().map(|(n, b)| (d.join(n), kept.join(n), *b));
    let agents = d.parent().map(|c| (c.join("AGENTS.md"), kept.join("AGENTS.md"), AGENTS));
    for (p, was, body) in files.chain(agents) {
        let mine = std::fs::read_to_string(&p).ok();
        let untouched = mine.is_none() || mine == std::fs::read_to_string(&was).ok();
        if untouched && mine.as_deref() != Some(body) && std::fs::write(&p, body).is_ok() && p.extension().is_none() {
            make_exec(&p);
        }
        if untouched {
            let _ = std::fs::write(&was, body);
        }
    }
}

fn status_file(name: &str) -> PathBuf {
    PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".cache/halftone/modules").join(format!("{name}.status"))
}

/// "12s ago · ok" or "12s ago · error: ..." from the last run, or "never run".
pub fn status(name: &str) -> String {
    match std::fs::read_to_string(status_file(name)).ok().and_then(|s| s.split_once('\t').map(|(t, m)| (t.parse::<f64>().unwrap_or(0.0), m.trim().to_string()))) {
        Some((t, m)) => format!("{} · {m}", super::cards::ago(t)),
        None => "never run".into(),
    }
}

/// Runs the module once with a timeout: stdout parsed, or the first thing that went wrong.
pub fn exec(name: &str) -> Result<Out, String> {
    let r = exec_raw(name).map(|s| parse(&s));
    let msg = match &r {
        Ok(_) => "ok".to_string(),
        Err(e) => format!("error: {e}"),
    };
    let f = status_file(name);
    if let Some(d) = f.parent() {
        let _ = std::fs::create_dir_all(d);
    }
    let _ = std::fs::write(f, format!("{}\t{msg}", super::cards::now_unix()));
    r
}

pub fn exec_raw(name: &str) -> Result<String, String> {
    if !exists(name) {
        return Err(format!("no module {}", path(name).display()));
    }
    // Scripts call `"$HALFTONE" secret get <name>` for the tokens `connect:` saved.
    let me = std::env::current_exe().unwrap_or_else(|_| "halftone".into());
    let mut child = Command::new(path(name)).env("HALFTONE", me).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().map_err(|e| format!("{e} (chmod +x {})", path(name).display()))?;
    let drain = |mut r: Box<dyn Read + Send>| std::thread::spawn(move || { let mut s = String::new(); let _ = r.read_to_string(&mut s); s });
    let (out, err) = (drain(Box::new(child.stdout.take().unwrap())), drain(Box::new(child.stderr.take().unwrap())));
    let t0 = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(s)) => break s,
            Ok(None) if t0.elapsed() > Duration::from_secs(10) => {
                let _ = child.kill();
                return Err("timed out after 10s".into());
            }
            Ok(None) => std::thread::sleep(Duration::from_millis(40)),
            Err(e) => return Err(e.to_string()),
        }
    };
    let (out, err) = (out.join().unwrap_or_default(), err.join().unwrap_or_default());
    if status.success() {
        Ok(out)
    } else {
        Err(err.lines().rev().find(|l| !l.trim().is_empty()).map_or(format!("exit {}", status.code().unwrap_or(-1)), |l| l.trim().to_string()))
    }
}

/// Opens a URL, or runs anything that is not one as a shell command.
pub fn open(target: &str) {
    if target.contains("://") || target.starts_with("mailto:") {
        let cmd = if cfg!(target_os = "macos") { "open" } else { "xdg-open" };
        let _ = Command::new(cmd).arg(target).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn();
    } else {
        let _ = Command::new("sh").args(["-c", target]).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn();
    }
}

#[derive(Default)]
pub struct Slot {
    pub out: Option<Out>,
    pub err: Option<String>,
}

/// One refresh thread per module on the desk; results come back over a channel.
pub struct Mods {
    tx: Sender<(String, Result<Out, String>)>,
    rx: Receiver<(String, Result<Out, String>)>,
    pub slots: HashMap<String, Slot>,
}

impl Mods {
    pub fn new() -> Mods {
        let (tx, rx) = mpsc::channel();
        Mods { tx, rx, slots: HashMap::new() }
    }

    /// The slot for `name`, starting its refresh thread the first time it is asked for.
    pub fn get(&mut self, name: &str) -> &Slot {
        if !self.slots.contains_key(name) {
            let (tx, n) = (self.tx.clone(), name.to_string());
            std::thread::spawn(move || {
                let mut every = 60;
                loop {
                    let r = exec(&n);
                    if let Ok(o) = &r {
                        every = o.every;
                    }
                    if tx.send((n.clone(), r)).is_err() {
                        return;
                    }
                    std::thread::sleep(Duration::from_secs(every));
                }
            });
            self.slots.insert(name.into(), Slot::default());
        }
        &self.slots[name]
    }

    /// Runs the module once now, outside its interval (after a connect saved a secret).
    pub fn refresh(&self, name: &str) {
        let (tx, n) = (self.tx.clone(), name.to_string());
        std::thread::spawn(move || _ = tx.send((n.clone(), exec(&n))));
    }

    pub fn drain(&mut self) {
        while let Ok((name, r)) = self.rx.try_recv() {
            let s = self.slots.entry(name).or_default();
            match r {
                Ok(o) => (s.out, s.err) = (Some(o), None),
                Err(e) => s.err = Some(e),
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_the_protocol() {
        let o = parse("title: Hi\nevery: 30\nopen: https://x.y\nbig: 72F\nrow: Wind | 5 mph | warn\nrow: Solo\nbar: Disk | 1.7 | bad\nspark: 1 2,3\nlink: HN | https://hn.com\nlink: broken\ntext: quiet\nerror: boom\nstray: line\n\n");
        assert_eq!((o.title.as_deref(), o.every, o.open.as_deref()), (Some("Hi"), 30, Some("https://x.y")));
        assert_eq!(o.lines, vec![
            Line::Big("72F".into()),
            Line::Row("Wind".into(), "5 mph".into(), Some("warn".into())),
            Line::Row("Solo".into(), "".into(), None),
            Line::Bar("Disk".into(), 1.0, Some("bad".into())),
            Line::Spark(vec![1.0, 2.0, 3.0]),
            Line::Link("HN".into(), "https://hn.com".into(), String::new()),
            Line::Text("broken".into()),
            Line::Text("quiet".into()),
            Line::Error("boom".into()),
            Line::Text("stray: line".into()),
        ]);
        assert_eq!(parse("").every, 60);
    }

    #[test]
    fn parses_connect_and_headers() {
        let o = parse("connect: todoist | https://app.todoist.com/x?a=b | your API token\nbig: hi");
        assert_eq!(o.connect, Some(("todoist".into(), "https://app.todoist.com/x?a=b".into(), "your API token".into())));
        assert_eq!(o.lines, vec![Line::Big("hi".into())]);
        assert_eq!(parse("connect: a | http://u").connect.unwrap().2, "your key");
        assert_eq!(parse("connect: lonely").connect, None);
        assert_eq!(meta("#!/bin/sh\n# about: Hi there\n# group: Finance\necho"), ("Hi there".into(), "Finance".into()));
        assert_eq!(meta("#!/bin/sh\n\n\n\n\n# about: too late"), (String::new(), String::new()));
    }

    #[test]
    fn builtin_scripts_are_valid_sh() {
        for (name, body) in BUILTIN {
            let f = std::env::temp_dir().join(format!("halftone-sh-check-{name}"));
            std::fs::write(&f, body).unwrap();
            let ok = Command::new("sh").arg("-n").arg(&f).status().unwrap().success();
            let _ = std::fs::remove_file(&f);
            assert!(ok, "{name} fails sh -n");
        }
    }
}
